effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:
 //////////////////////////
 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////


     // Converts a single linear channel to srgb
     float linear_to_srgb(float channel) {
         if(channel <= 0.0031308)
             return 12.92 * channel;
         else
             return (1.0 + SRGB_ALPHA) * pow(channel, 1.0/SRGB_GAMMA) - SRGB_ALPHA;
     }

     // Converts a single srgb channel to rgb
     float srgb_to_linear(float channel) {
         if (channel <= 0.04045)
             return channel / 12.92;
         else
             return pow((channel + SRGB_ALPHA) / (1.0 + SRGB_ALPHA), SRGB_INVERSE_GAMMA);
     }

     // Converts a linear rgb color to a srgb color (exact, not approximated)
     vec3 rgb_to_srgb(vec3 rgb) {
         return vec3(
             linear_to_srgb(rgb.r),
             linear_to_srgb(rgb.g),
             linear_to_srgb(rgb.b)
         );
     }

     // Converts a srgb color to a linear rgb color (exact, not approximated)
     vec3 srgb_to_rgb(vec3 srgb) {
         return vec3(
             srgb_to_linear(srgb.r),
             srgb_to_linear(srgb.g),
             srgb_to_linear(srgb.b)
         );
     }

     float bayer2(vec2 v)
     {
         v=floor(v);
      return fract(v.y*v.y*.75+v.x*.5);   
     }
     float bayer4(vec2 v)
     {
         return bayer2(.5*v)*.25+bayer2(v);
     }
     float bayer8(vec2 v)
     {
         return bayer4(.5*v)*.25+bayer2(v);
     }
     float bayer16(vec2 v)
     {
         return bayer8(.5*v)*.25+bayer2(v);
     }
     float bayer32(vec2 v)
     {
         return bayer16(.5*v)*.25+bayer2(v);
     }
     float bayer64(vec2 v)
     {
         return bayer32(.5*v)*.25+bayer2(v);
     }
     float bayer128(vec2 v)
     {
         return bayer64(.5*v)*.25+bayer2(v);
     }
 //////////////////////////
     void main() {
     if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);

     /////////////////////////

 	vec4 fragColor;

         vec2 uv = acScreenNorm.st;
         // vec2 uv = I.xy / iResolution.xy;
         float d = bayer128(fragCoord)+0.00003051757;
         #define s floor(pow(2.0, 1.9)-1.0)
         fragColor.rgb = srgb_to_rgb(texture2DCv(inputImg.texture,uv).rgb);
         fragColor.rgb = rgb_to_srgb(floor(fragColor.rgb*s+d)/s);

 	vec4 factor = mix(texColorX,fragColor,1.0);

 	float hardness = 1.0;
     vec4 resultfinal;
       if( blendMode==0 ) {
         resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; 
         resultfinal = (newLayer(texColorX, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
       }
     }
